<script setup>
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue';
import { useEditor, EditorContent } from '@tiptap/vue-3';
import StarterKit from '@tiptap/starter-kit';
import { Feather, Plus, FileText, LayoutDashboard, Settings, Sparkles, Check, X, ArrowRight, Moon, Sun, ChevronLeft, Search, Trash2, Bold, Italic, List, Undo2, Redo2, WandSparkles, ShieldCheck, AlertCircle, RefreshCw, Menu } from 'lucide-vue-next';
import ConnectionSettings from './ConnectionSettings.vue';
import { api } from './lib/api';
import { Suggestions, decorate } from './lib/suggestions';
import { blocksFromDoc, applySuggestion, selectionSnapshot, applyRewrite } from './lib/anchors';
const page=ref('dashboard'), docs=ref([]), search=ref(''), current=ref(null), title=ref(''), revision=ref(0), suggestions=ref([]), selected=ref(null);
const settings=ref({mode:'grammar',live_analysis:true,dark_mode:false}), modes=ref([]), meta=ref({version:'',provider:'',configured:false,debounce_ms:700});
const loading=ref(true), busy=ref(false), switching=ref(false), error=ref(''), saveState=ref('Saved'), dirty=ref(false), mobileNav=ref(false), filter=ref('all');
const rewrite=ref(null), rewriteBusy=ref(false), action=ref('natural'), selectedText=ref(false), ignored=ref(new Set()), analyzed=ref(false), explanationBusy=ref(false);
let analysisTimer, saveTimer, controller, rewriteController, generation=0, analysisRun=0, savePromise=null, changeCounter=0, hydrating=false;
const editor=useEditor({extensions:[StarterKit.configure({heading:{levels:[1,2,3]},codeBlock:false,link:false,trailingNode:false}),Suggestions.configure({onSelect:id=>{selected.value=id;}})],content:{type:'doc',content:[{type:'paragraph'}]},editorProps:{attributes:{class:'writing-surface','aria-label':'Writing editor',role:'textbox','aria-multiline':'true'}},onUpdate:()=>{if(!hydrating) changed();},onSelectionUpdate:({editor})=>{selectedText.value=!!selectionSnapshot(editor,revision.value);}});
const wordCount=computed(()=>{revision.value;return editor.value?.getText().trim().split(/\s+/u).filter(Boolean).length||0;});
const charCount=computed(()=>{revision.value;return Array.from(editor.value?.getText()||'').length;});
const visibleDocs=computed(()=>docs.value.filter(d=>d.title.toLowerCase().includes(search.value.toLowerCase())));
const visibleSuggestions=computed(()=>suggestions.value.filter(s=>filter.value==='all'||s.category===filter.value));
const selectedSuggestion=computed(()=>suggestions.value.find(s=>s.id===selected.value));
const score=computed(()=>Math.max(0,100-suggestions.value.reduce((n,s)=>n+({high:12,medium:7,low:3}[s.severity]||5),0)));
const activeMode=computed(()=>modes.value.find(m=>m.id===settings.value.mode)?.label||'Grammar Only');
const actions=[['grammar','Fix grammar'],['improve','Improve sentence'],['natural','Make natural'],['professional','Make professional'],['friendly','Make friendly'],['romantic','Make romantic'],['shorten','Shorten'],['expand','Expand']];
const emptyDoc=()=>({type:'doc',content:[{type:'paragraph'}]});
function cancelAnalysis(){clearTimeout(analysisTimer);controller?.abort();analysisRun++;busy.value=false;}
function invalidate(){cancelAnalysis();rewriteController?.abort();rewriteBusy.value=false;rewrite.value=null;revision.value++;suggestions.value=[];selected.value=null;analyzed.value=false;if(editor.value)decorate(editor.value,[],revision.value);}
function changed(){invalidate();dirty.value=true;changeCounter++;saveState.value='Unsaved';ignored.value=new Set();clearTimeout(saveTimer);saveTimer=setTimeout(()=>save().catch(()=>{}),900);scheduleAnalysis();}
function titleChanged(){dirty.value=true;changeCounter++;saveState.value='Unsaved';clearTimeout(saveTimer);saveTimer=setTimeout(()=>save().catch(()=>{}),900);}
function scheduleAnalysis(){cancelAnalysis();if(settings.value.live_analysis && page.value==='editor') analysisTimer=setTimeout(analyze,meta.value.debounce_ms);}
async function analyze(){
  cancelAnalysis();if(!editor.value || !current.value)return;
  const blocks=blocksFromDoc(editor.value.state.doc).map(({id,text})=>({id,text}));
  if(blocks.reduce((n,b)=>n+Array.from(b.text).length,0)>12000 || blocks.length>200){error.value='Live analysis supports up to 12,000 characters and 200 paragraphs. Your document can still be saved.';return;}
  if(!blocks.some(b=>b.text.trim())){suggestions.value=[];analyzed.value=false;return;}
  const rev=revision.value,gen=generation,run=analysisRun;controller=new AbortController();busy.value=true;
  try{const result=await api('writing/analyze',{method:'POST',body:{blocks,revision:rev,mode:settings.value.mode},signal:controller.signal});
    if(gen!==generation || revision.value!==rev || run!==analysisRun || result.revision!==rev)return;
    suggestions.value=result.suggestions.filter(s=>!ignored.value.has(s.id));decorate(editor.value,suggestions.value,rev);analyzed.value=true;
  }catch(e){if(e.name!=='AbortError'&&gen===generation&&run===analysisRun)error.value=e.message;}
  finally{if(run===analysisRun)busy.value=false;}
}
function accept(s){if(!applySuggestion(editor.value,s,revision.value)){error.value='This suggestion is out of date. Analyze the current text again.';invalidate();}}
function ignore(s){ignored.value.add(s.id);suggestions.value=suggestions.value.filter(x=>x.id!==s.id);selected.value=null;decorate(editor.value,suggestions.value,revision.value);}
async function save(){
  clearTimeout(saveTimer);
  if(savePromise){await savePromise;if(dirty.value)return save();return;}
  if(!dirty.value||!current.value)return;
  const id=current.value.id,count=changeCounter,gen=generation;
  const body={title:title.value.trim()||'Untitled document',content:editor.value.getJSON(),version:current.value.version};
  saveState.value='Saving…';
  savePromise=(async()=>{try{const result=await api('documents/'+id,{method:'PUT',body});if(gen!==generation)return;current.value=result;const ix=docs.value.findIndex(d=>d.id===id);if(ix>=0)docs.value[ix]=result;dirty.value=changeCounter!==count;saveState.value=dirty.value?'Unsaved':'Saved';}
    catch(e){saveState.value='Save failed';error.value=e.message;throw e;}finally{savePromise=null;}})();
  await savePromise;if(dirty.value)return save();
}
async function refreshDocs(){let pageNumber=1,all=[];while(true){const result=await api('documents?page='+pageNumber);all.push(...result.data);if(!result.next_page_url)break;pageNumber++;}docs.value=all;}
async function navigate(target){if(switching.value)return;switching.value=true;try{await save();page.value=target;mobileNav.value=false;invalidate();}catch{}finally{switching.value=false;}}
async function openDocument(id){if(switching.value)return;switching.value=true;try{await save();const doc=await api('documents/'+id);generation++;invalidate();current.value=doc;title.value=doc.title;hydrating=true;editor.value.commands.setContent(doc.content,{emitUpdate:false});hydrating=false;dirty.value=false;saveState.value='Saved';page.value='editor';mobileNav.value=false;selectedText.value=false;ignored.value=new Set();scheduleAnalysis();}catch(e){error.value=e.message;}finally{switching.value=false;}}
async function newDocument(demo=false){if(switching.value)return;switching.value=true;try{await save();const content=demo?{type:'doc',content:[{type:'paragraph',content:[{type:'text',text:'I is excited to share teh first draft. She go to the studio every morning. I hope to recieve your feedback soon.'}]}]}:emptyDoc();const doc=await api('documents',{method:'POST',body:{title:demo?'A little room to improve':'Untitled document',content}});docs.value.unshift(doc);switching.value=false;await openDocument(doc.id);}catch(e){error.value=e.message;}finally{switching.value=false;}}
async function deleteDocument(doc){if(!confirm(`Delete “${doc.title}”? This cannot be undone.`))return;try{await api('documents/'+doc.id,{method:'DELETE',body:{version:doc.version}});docs.value=docs.value.filter(d=>d.id!==doc.id);}catch(e){error.value=e.message;}}
async function connectionChanged(){invalidate();try{meta.value=await api('writing/settings');}catch(e){error.value=e.message;}}
async function updateSettings(patch){try{const result=await api('writing/settings',{method:'PUT',body:patch});settings.value=result.settings;if('mode'in patch){ignored.value=new Set();invalidate();}scheduleAnalysis();}catch(e){error.value=e.message;}}
async function requestRewrite(){
  const snapshot=selectionSnapshot(editor.value,revision.value);if(!snapshot){error.value='Select text within one paragraph to rewrite it.';return;}
  if(Array.from(snapshot.text).length>6000){error.value='Select 6,000 characters or fewer.';return;}
  rewriteController?.abort();rewriteController=new AbortController();rewriteBusy.value=true;rewrite.value=null;const gen=generation;
  try{const result=await api('writing/rewrite',{method:'POST',body:{text:snapshot.text,mode:settings.value.mode,action:action.value,revision:snapshot.revision},signal:rewriteController.signal});if(gen===generation&&snapshot.revision===revision.value)rewrite.value={...snapshot,...result};}
  catch(e){if(e.name!=='AbortError'&&gen===generation)error.value=e.message;}finally{if(gen===generation)rewriteBusy.value=false;}
}
function acceptRewrite(){const preview=rewrite.value;if(!preview)return;if(!applyRewrite(editor.value,preview,preview.replacement,revision.value))error.value='The selected passage changed. Request a new rewrite.';rewrite.value=null;}
async function explain(s){explanationBusy.value=true;const gen=generation,rev=revision.value;try{const result=await api('writing/explain',{method:'POST',body:{original:s.original,replacement:s.replacement}});if(gen===generation&&rev===revision.value)s.explanation=result.explanation;}catch(e){if(gen===generation)error.value=e.message;}finally{explanationBusy.value=false;}}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue='';}}
watch(()=>settings.value.dark_mode,v=>document.documentElement.classList.toggle('dark',v),{immediate:true});
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);try{const [config,availableModes]=await Promise.all([api('writing/settings'),api('writing/modes')]);meta.value=config;settings.value=config.settings;if(new URLSearchParams(location.search).has('connection')){page.value='settings';history.replaceState(null,'',location.pathname);}modes.value=availableModes;await refreshDocs();}catch(e){error.value=e.message;}finally{loading.value=false;}});
onBeforeUnmount(()=>{cancelAnalysis();rewriteController?.abort();clearTimeout(saveTimer);window.removeEventListener('beforeunload',beforeUnload);editor.value?.destroy();});
</script>

<template>
<div class="workspace">
  <aside class="nav-panel" :class="{'nav-open':mobileNav}">
    <a class="brand" href="#" @click.prevent="navigate('dashboard')"><span class="brand-icon"><Feather :size="23" /></span>chat<span>Helper</span></a>
    <button class="new-button" @click="newDocument()" :disabled="loading||switching"><Plus :size="18"/> New document <span>↗</span></button>
    <div class="nav-caption">WORKSPACE</div>
    <nav aria-label="Main navigation">
      <button :class="{active:page==='dashboard'}" @click="navigate('dashboard')"><LayoutDashboard :size="18"/> Dashboard</button>
      <button :class="{active:page==='documents'||page==='editor'}" @click="navigate('documents')"><FileText :size="18"/> My documents <small>{{docs.length}}</small></button>
      <button :class="{active:page==='settings'}" @click="navigate('settings')"><Settings :size="18"/> Settings</button>
    </nav>
    <div class="sidebar-bottom"><div class="private-card"><ShieldCheck :size="20"/><strong>Your space. Your words.</strong><p>Documents stay on this computer. AI requests use your configured provider.</p></div><div class="profile"><span class="avatar">Y</span><div><strong>Personal workspace</strong><small>Local single-user edition</small></div><button class="icon-btn" aria-label="Toggle dark mode" @click="updateSettings({dark_mode:!settings.dark_mode})"><Sun v-if="settings.dark_mode" :size="17"/><Moon v-else :size="17"/></button></div><p class="version">chatHelper v{{meta.version||'…'}}</p></div>
  </aside>
  <main class="main-panel">
    <header class="topbar"><div class="breadcrumbs"><button class="icon-btn mobile-menu" aria-label="Open navigation" @click="mobileNav=!mobileNav"><Menu :size="20"/></button><span>Workspace</span><span class="slash">/</span><strong>{{page==='editor'?'Writing studio':page==='settings'?'Settings':page==='documents'?'My documents':'Overview'}}</strong></div><div class="topbar-right"><span class="local-dot"></span> Local workspace <span class="avatar small">Y</span></div></header>
    <div v-if="error" class="error-banner" role="alert"><AlertCircle :size="18"/><span>{{error}}</span><button class="icon-btn" aria-label="Dismiss error" @click="error='' "><X :size="17"/></button></div>
    <div v-if="loading" class="loading-state"><RefreshCw class="spin"/> Opening your workspace…</div>
    <template v-else>
      <div v-if="page==='dashboard'||page==='documents'" class="dashboard">
        <div class="page-heading"><div><div class="eyebrow">A LITTLE CLARITY GOES A LONG WAY</div><h1>{{page==='dashboard'?'Good words start here.':'Your words, all together.'}}</h1><p>A quieter space to think, write, and find the words you mean.</p></div><button class="primary" @click="newDocument()" :disabled="switching"><Plus :size="17"/> New document</button></div>
        <section v-if="page==='dashboard'" class="hero-card"><div class="hero-copy"><span class="pill"><Sparkles :size="13"/> YOUR VOICE, A LITTLE CLEARER</span><h2>Let your ideas flow.<br><span>We’ll help with the words.</span></h2><p>From the first thought to the final full stop. Catch mistakes, find a natural tone, and write with a little more confidence.</p><button class="hero-link" @click="newDocument(true)">Try the writing studio <ArrowRight :size="17"/></button></div><div class="hero-paper" aria-hidden="true"><div class="paper-top"><span></span><span></span><span></span><small>A fresh perspective</small></div><p>Good ideas deserve<br><span class="sample-error">teh</span> right words.</p><div class="sample-correction"><span class="check-circle"><Check :size="14"/></span><div><small>SPELLING</small><strong>teh <ArrowRight :size="13"/> the</strong></div><Sparkles :size="18"/></div><div class="paper-lines"><i></i><i></i></div></div></section>
        <div v-if="page==='dashboard'" class="stats-row"><div><span class="stat-icon mint"><FileText :size="19"/></span><div><strong>{{docs.length}}</strong><small>Documents in your space</small></div></div><div><span class="stat-icon lilac"><WandSparkles :size="19"/></span><div><strong>8 writing modes</strong><small>A tone for every moment</small></div></div><div><span class="stat-icon peach"><ShieldCheck :size="19"/></span><div><strong>{{meta.provider==='mock'?'Mock demo':'Your AI, your control'}}</strong><small>{{meta.provider==='mock'?'Deterministic examples · no AI calls':'Text is sent only for AI requests'}}</small></div></div></div>
        <div class="section-heading"><h2>{{page==='dashboard'?'Recent documents':'My documents'}} <span>{{docs.length}}</span></h2><label class="search-box"><Search :size="16"/><input aria-label="Search documents" v-model="search" placeholder="Find a document…"/></label></div>
        <div class="document-grid"><button class="document-card create-card" @click="newDocument()" :disabled="switching"><span class="create-icon"><Plus :size="25"/></span><strong>Start something new</strong><small>A blank page, endless possibilities.</small></button><article class="document-card" v-for="doc in visibleDocs" :key="doc.id"><div class="doc-top"><span class="doc-icon"><FileText :size="22"/></span><button class="icon-btn delete-button" :aria-label="'Delete '+doc.title" @click="deleteDocument(doc)"><Trash2 :size="16"/></button></div><button class="doc-open" @click="openDocument(doc.id)" :disabled="switching"><h3>{{doc.title}}</h3><p>Pick up where you left off.</p><div class="doc-bottom"><span>{{new Date(doc.updated_at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}}</span><ArrowRight :size="17"/></div></button></article></div><p v-if="search&&!visibleDocs.length" class="muted">No documents match your search.</p>
        <div class="quiet-footer"><Feather :size="15"/> Make room for your next good thought.</div>
      </div>
      <div v-else-if="page==='editor'" class="studio">
        <section class="editor-column">
          <div class="editor-heading"><button class="icon-btn" aria-label="Back to documents" @click="navigate('documents')"><ChevronLeft :size="20"/></button><input class="document-title" aria-label="Document title" v-model="title" maxlength="160" @input="titleChanged"/><button class="save-status" @click="save().catch(()=>{})" :class="{'save-failed':saveState==='Save failed'}"><Check v-if="saveState==='Saved'" :size="14"/><RefreshCw v-else :size="14"/>{{saveState}}</button></div>
          <div class="formatbar" v-if="editor"><div class="format-buttons"><button class="format-btn" :class="{active:editor.isActive('bold')}" aria-label="Bold" @click="editor.chain().focus().toggleBold().run()"><Bold :size="17"/></button><button class="format-btn" :class="{active:editor.isActive('italic')}" aria-label="Italic" @click="editor.chain().focus().toggleItalic().run()"><Italic :size="17"/></button><button class="format-btn" aria-label="Heading" @click="editor.chain().focus().toggleHeading({level:2}).run()">H2</button><button class="format-btn" aria-label="Bullet list" @click="editor.chain().focus().toggleBulletList().run()"><List :size="18"/></button><span class="toolbar-divider"></span><button class="format-btn" aria-label="Undo" :disabled="!editor.can().undo()" @click="editor.chain().focus().undo().run()"><Undo2 :size="17"/></button><button class="format-btn" aria-label="Redo" :disabled="!editor.can().redo()" @click="editor.chain().focus().redo().run()"><Redo2 :size="17"/></button></div><label class="mode-select"><Sparkles :size="15"/><select aria-label="Writing mode" :value="settings.mode" @change="updateSettings({mode:$event.target.value})"><option v-for="mode in modes" :value="mode.id" :key="mode.id">{{mode.label}}</option></select></label></div>
          <div class="paper-area"><div class="editor-page"><div class="editor-page-caption">YOUR THOUGHTS, IN YOUR OWN WORDS</div><EditorContent :editor="editor"/><div v-if="!wordCount" class="editor-empty-hint">Start writing here. There’s no perfect first draft.</div><div v-if="selectedSuggestion" class="suggestion-popover" role="dialog" aria-label="Selected correction"><div class="category-label" :class="selectedSuggestion.category">{{selectedSuggestion.category}}</div><p><del>{{selectedSuggestion.original}}</del> → <strong>{{selectedSuggestion.replacement||'(remove)'}}</strong></p><p class="explanation">{{selectedSuggestion.explanation}}</p><div class="card-actions"><button class="primary" @click="accept(selectedSuggestion)"><Check :size="15"/>Accept</button><button class="text-btn" @click="ignore(selectedSuggestion)">Ignore</button><button class="icon-btn" aria-label="Close suggestion" @click="selected=null"><X :size="15"/></button></div></div></div></div>
          <div class="rewrite-toolbar"><WandSparkles :size="18"/><select aria-label="Rewrite action" v-model="action"><option v-for="[id,label] in actions" :key="id" :value="id">{{label}}</option></select><button class="primary" :disabled="!selectedText||rewriteBusy" @mousedown.prevent @click="requestRewrite">{{rewriteBusy?'Rewriting…':'Rewrite selection'}}<ArrowRight :size="15"/></button><span>Select a passage within one paragraph</span></div>
          <div class="editor-footer"><span>{{wordCount}} words <i>·</i> {{charCount}} characters</span><span>English <i>·</i> {{activeMode}}</span></div>
        </section>
        <aside class="insights"><div class="insights-heading"><h2>Writing assistant</h2><Sparkles :size="18"/></div><div class="provider-label" :class="{'mock-label':meta.provider==='mock'}">{{meta.provider==='mock'?'MOCK DEMO · LIMITED RULES':meta.provider==='chatgpt'?'CHATGPT SUBSCRIPTION':'OPENAI API · SEPARATE BILLING'}}</div><div class="score-card"><div class="score-circle">{{analyzed?score:'—'}}</div><div><strong>{{busy?'Finding the right words…':analyzed?(suggestions.length?'A little polish goes a long way':'Looking good!'):'Make every word count.'}}</strong><p>{{analyzed?'Heuristic score · not a quality guarantee':'Your suggestions will appear here.'}}</p></div></div><div class="analysis-controls"><label><input type="checkbox" :checked="settings.live_analysis" @change="updateSettings({live_analysis:$event.target.checked})"/> Live analysis</label><button class="icon-btn" aria-label="Analyze now" :disabled="busy" @click="analyze"><RefreshCw :size="16" :class="{spin:busy}"/></button></div><p class="privacy-note">{{meta.provider==='mock'?'Mock mode uses demonstration rules. No text is sent to OpenAI.':'Live analysis sends document text to OpenAI. Rewrites and explanations also send the selected text.'}}</p><p class="configuration-note" v-if="!meta.configured">Open Settings to connect an API key or ChatGPT account and select a model.</p><div class="suggestion-tabs"><button :class="{active:filter==='all'}" @click="filter='all'">All <span>{{suggestions.length}}</span></button><button :class="{active:filter==='grammar'}" @click="filter='grammar'">Grammar</button><button :class="{active:filter==='clarity'}" @click="filter='clarity'">Clarity</button><button :class="{active:filter==='style'}" @click="filter='style'">Style</button><button :class="{active:filter==='spelling'}" @click="filter='spelling'">Spelling</button></div><div class="suggestion-list"><article v-for="s in visibleSuggestions" :key="s.id" class="suggestion-card" :class="{selected:selected===s.id}"><button class="suggestion-select" @click="selected=s.id"><span class="category-label" :class="s.category">{{s.category}}</span><p><del>{{s.original}}</del><ArrowRight :size="14"/><strong>{{s.replacement||'(remove)'}}</strong></p></button><p class="explanation">{{s.explanation}}</p><div class="card-actions"><button class="accept-btn" @click="accept(s)"><Check :size="14"/> Accept</button><button class="text-btn" @click="ignore(s)">Ignore</button><button class="explain-btn" :disabled="explanationBusy" @click="explain(s)">Explain</button></div></article><div v-if="!visibleSuggestions.length" class="empty-suggestions"><span><Feather :size="25"/></span><strong>{{busy?'Taking a closer look…':analyzed?'You’re all caught up.':'A fresh page. A fresh start.'}}</strong><p>{{busy?'Keep writing. We’ll catch up.':analyzed?'No suggestions in this category.':'Write a few lines or use Analyze now to get started.'}}</p></div></div></aside>
      </div>
      <div v-else-if="page==='settings'" class="settings-page"><div class="eyebrow">MAKE YOURSELF AT HOME</div><h1>Your writing preferences.</h1><p class="muted">Small adjustments for a workspace that feels like you.</p><section class="settings-card"><h2>Writing & appearance</h2><label class="setting-row"><div><strong>Default writing mode</strong><p>Set the tone without changing your document.</p></div><select :value="settings.mode" @change="updateSettings({mode:$event.target.value})"><option v-for="m in modes" :key="m.id" :value="m.id">{{m.label}}</option></select></label><label class="setting-row"><div><strong>Live analysis</strong><p>Automatically send text to your provider after a typing pause.</p></div><input type="checkbox" :checked="settings.live_analysis" @change="updateSettings({live_analysis:$event.target.checked})"/></label><label class="setting-row"><div><strong>Dark mode</strong><p>A softer workspace for late-night thoughts.</p></div><input type="checkbox" :checked="settings.dark_mode" @change="updateSettings({dark_mode:$event.target.checked})"/></label></section><ConnectionSettings :meta="meta" @changed="connectionChanged"/><p class="version">chatHelper v{{meta.version}} · Local single-user MVP</p></div>
    </template>
  </main>
  <div v-if="rewrite" class="modal-backdrop" @click.self="rewrite=null"><section class="rewrite-modal" role="dialog" aria-modal="true" aria-label="Rewrite preview"><div class="modal-heading"><span class="pill"><WandSparkles :size="14"/> A FRESH TAKE</span><button class="icon-btn" aria-label="Close preview" @click="rewrite=null"><X :size="20"/></button></div><h2>Still your words. A little clearer.</h2><div class="rewrite-original"><small>ORIGINAL</small><p>{{rewrite.text}}</p></div><div class="rewrite-result"><small>SUGGESTED REWRITE</small><p>{{rewrite.replacement}}</p></div><p class="explanation">{{rewrite.explanation}}</p><div class="modal-actions"><button class="text-btn" @click="rewrite=null">Keep original</button><button class="primary" @click="acceptRewrite"><Check :size="16"/> Accept rewrite</button></div></section></div>
</div>
</template>
